import { useState } from 'react';

import axios from 'axios';

import { useNavigate } from 'react-router-dom';

function Register() {

    const navigate = useNavigate();

    const [name, setName] = useState('');

    const [email, setEmail] = useState('');
	const [phone, setPhone] = useState('');

    const [password, setPassword] = useState('');

    const register = async () => {

        try {

            await axios.post(

                '/api/register',

                {
                    name,
                    email,
		    phone,
                    password
                }
            );

            alert('Registration successful');

            navigate('/login');

        } catch (err) {

            alert('Registration failed');
        }
    };

    return (

        <div
            className="
                min-h-screen
                flex
                items-center
                justify-center
            "
        >

            <div
                className="
                    bg-white
                    p-10
                    rounded-3xl
                    border
                    shadow-lg
                    w-full
                    max-w-md
                "
            >

                <h1
                    className="
                        text-4xl
                        font-bold
                        mb-8
                        text-center
                    "
                >

                    Register

                </h1>

                <div className="grid gap-5">

                    <input
                        type="text"
                        placeholder="Name"
                        value={name}
                        onChange={(e) =>
                            setName(e.target.value)
                        }
                        className="
                            border
                            rounded-xl
                            p-4
                        "
                    />

                    <input
                        type="email"
                        placeholder="Email"
                        value={email}
                        onChange={(e) =>
                            setEmail(e.target.value)
                        }
                        className="
                            border
                            rounded-xl
                            p-4
                        "
                    />
	    <input
    type="text"
    placeholder="Phone Number"
    value={phone}
    onChange={(e) =>
        setPhone(e.target.value)
    }
    className="
        border
        rounded-xl
        p-4
    "
/>

                    <input
                        type="password"
                        placeholder="Password"
                        value={password}
                        onChange={(e) =>
                            setPassword(e.target.value)
                        }
                        className="
                            border
                            rounded-xl
                            p-4
                        "
                    />

                    <button
                        onClick={register}
                        className="
                            bg-blue-600
                            hover:bg-blue-700
                            text-white
                            py-4
                            rounded-xl
                            font-semibold
                        "
                    >

                        Register

                    </button>

                </div>

            </div>

        </div>
    );
}

export default Register;
