import { useEffect, useState } from 'react';

import axios from 'axios';

import { useParams } from 'react-router-dom';

function Question() {

    const { slug } = useParams();

    const [data, setData] = useState(null);

    const [answer, setAnswer] = useState('');

    useEffect(() => {

        axios
            .get(`/api/forum/question/${slug}`)
            .then((res) => {

                setData(res.data);
            });

    }, [slug]);

    if (!data) {

        return <div>Loading...</div>;
    }

    const submitAnswer = async () => {

        await axios.post(

            '/api/forum/answer',

            {
                question_id: data.question.id,
                answer,
                user_id: localStorage.getItem('user_id')
            }
        );

        window.location.reload();
    };

    return (

        <div className='max-w-5xl mx-auto py-10 px-6'>

            <div className='bg-white border rounded-3xl p-8 mb-10'>

                <h1 className='text-5xl font-bold mb-6'>

                    {data.question.title}

                </h1>

                <div
                    dangerouslySetInnerHTML={{
                        __html: data.question.content
                    }}
                />

            </div>

            <div className='space-y-6 mb-10'>

                {
                    data.answers.map((a) => (

                        <div
                            key={a.id}
                            className='bg-white border rounded-3xl p-6'
                        >

                            <div
                                dangerouslySetInnerHTML={{
                                    __html: a.answer
                                }}
                            />

                            <p className='text-slate-500 mt-4'>

                                Answered by {a.name}

                            </p>

                        </div>
                    ))
                }

            </div>

            <div className='bg-white border rounded-3xl p-8'>

                <h2 className='text-3xl font-bold mb-6'>

                    Your Answer

                </h2>

                <textarea
                    rows='8'
                    className='w-full border rounded-2xl p-5 mb-6'
                    value={answer}
                    onChange={(e) => setAnswer(e.target.value)}
                />

                <button
                    onClick={submitAnswer}
                    className='bg-blue-600 text-white px-8 py-4 rounded-2xl'
                >

                    Post Answer

                </button>

            </div>

        </div>
    );
}

export default Question;
