import { Link, useLocation } from 'react-router-dom';

function Navbar() {
  const location = useLocation();

  const user = JSON.parse(localStorage.getItem('user'));

  const isActive = (path) => location.pathname === path;

  const menuClass = (path) => {
    return isActive(path)
      ? "bg-slate-900 text-white px-4 py-2 rounded-xl font-semibold text-sm transition-all shadow-sm"
      : "text-slate-600 hover:text-slate-950 hover:bg-slate-100 px-4 py-2 rounded-xl font-semibold text-sm transition-all";
  };

  const logout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    window.location.href = '/login';
  };

  return (
    <header className='bg-white/80 backdrop-blur-md border-b border-slate-200/80 sticky top-0 z-50 shadow-sm'>
      <div className='max-w-7xl mx-auto px-6 py-4 flex items-center justify-between gap-4'>
        
        {/* BRAND IDENTITY LOGO UNIT */}
        <Link to='/' className='flex items-center gap-3 shrink-0 group'>
          <img
            src='/SI_logo_small.png'
            alt='Linux Docs'
            className='w-12 h-12 object-contain group-hover:scale-105 transition-transform'
            onError={(e) => { e.target.src = "/SI_logo.png" }}
          />
          <div>
            <h1 className='text-xl font-black tracking-tight text-slate-900 leading-tight'>
              LinuxDocs
            </h1>
            <p className='text-slate-400 text-xs font-bold uppercase tracking-wider hidden sm:block'>
              Engine Knowledge Hub
            </p>
          </div>
        </Link>

        {/* TOP LEVEL ROUTE NAV MENUS */}
        <nav className='hidden md:flex items-center gap-1'>
          <Link to='/' className={menuClass('/')}>Home</Link>
          <Link to='/issues' className={menuClass('/issues')}>Issues</Link>
          <Link to='/cheatsheets' className={menuClass('/cheatsheets')}>CheatSheets</Link>
          <Link to='/linux-crash' className={menuClass('/linux-crash')}>Crash Analysis</Link>
          <Link to='/forum' className={menuClass('/forum')}>Community Forum</Link>
        </nav>

        {/* SECURE IDENTITY AUTH CONTROLS */}
        <div className='flex items-center gap-3 font-medium text-sm'>
          {user ? (
            <div className="flex items-center gap-3">
              <span className="text-slate-600 hidden lg:inline font-medium">
                Hello, <span className="text-slate-900 font-bold">{user.name}</span>
              </span>
              <Link
                to="/admin"
                className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-xl shadow-sm font-semibold transition"
              >
                Admin Panel
              </Link>
              <button
                onClick={logout}
                className="border border-slate-200 text-slate-600 hover:text-red-600 hover:bg-red-50 px-4 py-2 rounded-xl font-semibold transition"
              >
                Logout
              </button>
            </div>
          ) : (
            <>
              <Link
                to='/login'
                className='text-slate-700 hover:text-slate-950 px-4 py-2 font-semibold transition'
              >
                Login
              </Link>
              <Link
                to='/register'
                className='bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-xl font-semibold shadow-sm transition'
              >
                Register
              </Link>
            </>
          )}
        </div>

      </div>
    </header>
  );
}

export default Navbar;
