import {
  BrowserRouter,
  Routes,
  Route,
  Link,
  useNavigate
} from 'react-router-dom';
import axios from 'axios';
import PrivacyPolicy from './pages/PrivacyPolicy';
import Navbar from './components/Navbar';
import ProtectedRoute from './components/ProtectedRoute';
import Home from './Home';
import Document from './Document';
import Tutorials from './Tutorials';
import Kubernetes from './Kubernetes';
import Docker from './Docker';
import Admin from './Admin';
import AdminList from './AdminList';
import EditDocument from './EditDocument';
import Login from './Login';
import Register from './Register';
import Issues from './pages/Issues';
import CheatSheets from './pages/CheatSheets';
import LinuxCrash from './pages/LinuxCrash';
import Networking from './pages/Networking';
import GPU from './pages/GPU';
import Forum from './pages/Forum';
import Question from './pages/Question';
import AskQuestion from './pages/AskQuestion';

function AppContent() {
  const navigate = useNavigate();
  const user = JSON.parse(localStorage.getItem('user'));

  const logout = async () => {
    try {
      const user = JSON.parse(localStorage.getItem('user'));
      if (user?.id) {
        await axios.post('/api/logout', { userId: user.id });
      }
      localStorage.removeItem('token');
      localStorage.removeItem('user');
      window.location.href = '/login';
    } catch (err) {
      console.log(err);
    }
  };

  return (
    // UNIFIED SYSTEM BACKGROUND (slate-50 ensures smooth eye comfort across views)
    <div className="min-h-screen bg-slate-50 text-slate-900 flex flex-col antialiased">
      
      {/* GLOBAL HEADER HEADER COMPONENT */}
      <Navbar />

      {/* CORE ROUTER MAIN WORKSPACE WRAPPER */}
      <main className="flex-1 w-full max-w-7xl mx-auto px-4 sm:px-6 py-8">
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/:slug" element={<Document />} />
          <Route path="/tutorials" element={<Tutorials />} />
          <Route path="/kubernetes" element={<Kubernetes />} />
          <Route path="/docker" element={<Docker />} />
          <Route path="/admin" element={<ProtectedRoute><Admin /></ProtectedRoute>} />
          <Route path="/admin/list" element={<AdminList />} />
          <Route path="/admin/edit/:id" element={<EditDocument />} />
          <Route path="/login" element={<Login />} />
          <Route path="/register" element={<Register />} />
          <Route path='/issues' element={<Issues />} />
          <Route path='/cheatsheets' element={<CheatSheets />} />
          <Route path='/linux-crash' element={<LinuxCrash />} />
          <Route path='/networking' element={<Networking />} />
          <Route path='/gpu' element={<GPU />} />
          <Route path='/forum' element={<Forum />} />
          <Route path='/forum/question/:id' element={<Question />} />
          <Route path='/ask-question' element={<AskQuestion />} />
          <Route path='/forum/:slug' element={<Question />} />
          <Route path="/privacy-policy" element={<PrivacyPolicy />} />
        </Routes>
      </main>

      {/* FULLY CENTERED CLEAN ARCHITECTURE FOOTER */}
      <footer className="bg-white border-t border-slate-200 mt-auto py-6">
        <div className="max-w-7xl mx-auto px-6 flex flex-col items-center justify-center text-center text-xs text-slate-500 font-medium gap-1.5">
          <div>
            © 2026 Linux Docs. All Rights Reserved. • <Link to="/privacy-policy" className="hover:text-blue-600 transition-colors font-bold">Privacy Policy</Link>
          </div>
          <div className="text-slate-400">
            Portal System Architect: <span className="font-semibold text-slate-600">KK</span>
          </div>
        </div>
      </footer>

    </div>
  );
}

function App() {
  return (
    <BrowserRouter>
      <AppContent />
    </BrowserRouter>
  );
}

export default App;
