import { useState } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import { GoogleLogin } from '@react-oauth/google';
import { jwtDecode } from 'jwt-decode';

function Login() {
    const navigate = useNavigate();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');

    const login = async () => {
        try {
            const res = await axios.post('/api/login', { email, password });
            localStorage.setItem('user_id', res.data.user.id);
            localStorage.setItem('name', res.data.user.name);
            localStorage.setItem('email', res.data.user.email);
            localStorage.setItem('token', res.data.token);
            localStorage.setItem('user', JSON.stringify(res.data.user));
            navigate('/admin');
        } catch (err) {
            alert('Invalid credentials');
        }
    };

    const googleSuccess = async (credentialResponse) => {
        try {
            const decoded = jwtDecode(credentialResponse.credential);
            const user = {
                name: decoded.name,
                email: decoded.email,
                picture: decoded.picture
            };
            localStorage.setItem('user', JSON.stringify(user));
            localStorage.setItem('token', credentialResponse.credential);
            navigate('/admin');
        } catch (err) {
            console.log(err);
        }
    };

    return (
        <div className="min-h-[70vh] flex items-center justify-center bg-transparent py-12">
            <div className="bg-white p-8 md:p-10 rounded-2xl border border-slate-200 shadow-xl w-full max-w-md">
                
                {/* Visual Header Identity */}
                <div className="text-center mb-8">
                    <div className="inline-flex p-3 bg-slate-900 text-emerald-400 rounded-xl mb-3 shadow-inner">
                        <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
                        </svg>
                    </div>
                    <h1 className="text-3xl font-black tracking-tight text-slate-900">Linux Docs Login</h1>
                    <p className="text-sm text-slate-500 mt-1 font-medium">Secure Admin Management Engine</p>
                </div>

                <div className="grid gap-5">
                    <div>
                        <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-2">Email Address</label>
                        <input
                            type="email"
                            placeholder="username@domain.com"
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            className="w-full border border-slate-300 rounded-xl p-3.5 focus:outline-none focus:ring-2 focus:ring-blue-600/20 focus:border-blue-600 transition text-slate-900 font-medium bg-slate-50 placeholder-slate-400"
                        />
                    </div>

                    <div>
                        <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-2">Password</label>
                        <input
                            type="password"
                            placeholder="••••••••••••"
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            className="w-full border border-slate-300 rounded-xl p-3.5 focus:outline-none focus:ring-2 focus:ring-blue-600/20 focus:border-blue-600 transition text-slate-900 font-medium bg-slate-50 placeholder-slate-400"
                        />
                    </div>

                    <button
                        onClick={login}
                        className="w-full bg-slate-900 hover:bg-slate-800 text-white py-3.5 rounded-xl font-bold text-sm tracking-wide transition-all shadow-md active:scale-[0.99] mt-2"
                    >
                        Sign In
                    </button>

                    <div className="relative my-3 flex items-center justify-center">
                        <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-slate-200"></div></div>
                        <span className="relative bg-white px-3 text-xs uppercase font-bold text-slate-400 tracking-wider">Identity Verification</span>
                    </div>

                    <div className="flex justify-center w-full shadow-sm rounded-xl overflow-hidden border border-slate-200 hover:bg-slate-50 transition">
                        <GoogleLogin
                            onSuccess={googleSuccess}
                            onError={() => console.log('Login Failed')}
                        />
                    </div>
                </div>

            </div>
        </div>
    );
}

export default Login;
