import { useEffect, useState } from 'react';
import axios from 'axios';
import { Link } from 'react-router-dom';

function Forum() {
    const [questions, setQuestions] = useState([]);

    useEffect(() => {
        axios.get('/api/forum/questions')
            .then((res) => setQuestions(res.data))
            .catch((err) => console.error(err));
    }, []);

    return (
        <div className='max-w-7xl mx-auto px-4 sm:px-6 py-6 space-y-6'>
            
            <div className='flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-slate-200 pb-6'>
                <div>
                    <h1 className='text-4xl font-black text-slate-900 tracking-tight'>Community Forum</h1>
                    <p className='text-slate-500 text-sm font-medium mt-0.5'>Share infrastructure issues and crowdsource runtime fixes.</p>
                </div>
                <Link
                    to='/ask-question'
                    className='inline-flex items-center justify-center bg-slate-900 hover:bg-slate-800 text-white px-5 py-2.5 rounded-xl text-xs font-bold shadow-md transition-all text-center'
                >
                    + Ask Question
                </Link>
            </div>

            <div className='space-y-3 pb-12'>
                {questions.map((q) => (
                    <Link
                        key={q.id}
                        to={`/forum/${q.slug}`}
                        className='block bg-white border border-slate-200 rounded-xl p-5 hover:border-blue-500 shadow-sm transition-all relative overflow-hidden group'
                    >
                        <div className="absolute left-0 top-0 bottom-0 w-1 bg-slate-200 group-hover:bg-blue-600 transition-colors"></div>
                        <div className="pl-2">
                            <h2 className='text-lg font-bold text-slate-900 group-hover:text-blue-600 transition-colors tracking-tight mb-1.5'>
                                {q.title}
                            </h2>
                            <p className='text-xs text-slate-400 font-medium flex items-center gap-1.5'>
                                <span>Engine Query Identity:</span> 
                                <span className="font-semibold text-slate-600">Asked by {q.name || "Anonymous System Engineer"}</span>
                            </p>
                        </div>
                    </Link>
                ))}

                {questions.length === 0 && (
                    <div className="text-center py-12 bg-white rounded-xl border border-dashed border-slate-300 p-6">
                        <p className="text-slate-500 text-sm font-medium">No system entries initialized in forum pipeline yet.</p>
                    </div>
                )}
            </div>
        </div>
    );
}

export default Forum;
