import { useEffect, useState } from 'react';

import axios from 'axios';

import {
    useParams,
    Link
} from 'react-router-dom';

function Document() {

    const { slug } = useParams();

    const [doc, setDoc] = useState(null);

    const [nav, setNav] = useState({});

    useEffect(() => {

        axios
            .get(`/api/documents/${slug}`)
            .then(res => {

                setDoc(res.data);

                return axios.get(
                    `/api/navigation/${res.data.id}`
                );
            })
            .then(navRes => {

                setNav(navRes.data);
            });

    }, [slug]);

    if (!doc) {

        return (

            <div className="text-center py-20">

                <h1 className="text-4xl font-bold">

                    Loading Article...

                </h1>

            </div>
        );
    }

    return (

        <div>

            {/* BACK BUTTON */}

            <div className="mb-6">

                <Link
                    to="/"
                    className="
                        text-blue-600
                        font-medium
                        hover:text-blue-800
                    "
                >

                    ← Back to Articles

                </Link>

            </div>

            {/* ARTICLE */}

            <article
                className="
                    max-w-5xl
                    mx-auto
                    bg-white
                    rounded-3xl
                    border
                    shadow-sm
                    p-12
                "
            >

                <div className="mb-10">

                    <h1
                        className="
                            text-6xl
                            font-extrabold
                            mb-4
                        "
                    >

                        {doc.title}

                    </h1>

                    <div className="text-slate-500">

                        Linux Documentation • DevOps Portal

                    </div>

                </div>

                <div
                    className="
                        prose
                        prose-xl
                        max-w-none
                        prose-slate
                    "
                    dangerouslySetInnerHTML={{
                        __html: doc.content
                    }}
                />

            </article>

            {/* NAVIGATION */}

            <div
                className="
                    max-w-5xl
                    mx-auto
                    mt-8
                    grid
                    grid-cols-2
                    gap-6
                "
            >

                {/* PREVIOUS */}

                <div>

                    {
                        nav.previous && (

                            <Link
                                to={`/${nav.previous.slug}`}
                                className="
                                    block
                                    bg-white
                                    border
                                    rounded-2xl
                                    p-6
                                    hover:shadow-lg
                                    transition
                                "
                            >

                                <p className="text-slate-500 mb-2">

                                    ← Previous

                                </p>

                                <h3 className="text-2xl font-bold">

                                    {nav.previous.title}

                                </h3>

                            </Link>
                        )
                    }

                </div>

                {/* NEXT */}

                <div>

                    {
                        nav.next && (

                            <Link
                                to={`/${nav.next.slug}`}
                                className="
                                    block
                                    bg-white
                                    border
                                    rounded-2xl
                                    p-6
                                    hover:shadow-lg
                                    transition
                                    text-right
                                "
                            >

                                <p className="text-slate-500 mb-2">

                                    Next →

                                </p>

                                <h3 className="text-2xl font-bold">

                                    {nav.next.title}

                                </h3>

                            </Link>
                        )
                    }

                </div>

            </div>

        </div>
    );
}

export default Document;
