import { useEffect, useState } from 'react';
import axios from 'axios';
import { Link } from 'react-router-dom';

import Sidebar from './components/Sidebar';
import SearchBar from './components/SearchBar';

function Home() {
    const [docs, setDocs] = useState([]);
    const [keyword, setKeyword] = useState('');

    useEffect(() => {
        axios
            .get('/api/documents')
            .then((res) => {
                setDocs(res.data);
            })
            .catch((err) => console.error("Error fetching docs:", err));
    }, []);

    const filteredDocs = docs.filter((doc) =>
        doc.title.toLowerCase().includes(keyword.toLowerCase())
    );
return (
    // Transparent wrapper lets the global #f1f5f9 background slide through perfectly
    <div className='max-w-7xl mx-auto px-4 sm:px-6 py-6 lg:py-10 bg-transparent'>
        <div className='flex flex-col lg:flex-row gap-8 lg:gap-10 items-start bg-transparent'>

            {/* DARK INFRASTRUCTURE SIDEBAR */}
            <Sidebar docs={docs} />

            {/* DYNAMIC DOCUMENTATION WORKSPACE */}
            <div className='flex-1 w-full space-y-6 bg-transparent'>

                {/* HERO IDENTITY HEADER */}
                <div className='border-b border-slate-300 pb-6'>
                    <h1 className='text-4xl sm:text-5xl font-black text-slate-900 tracking-tight mb-3'>
                        Linux Documentation Portal
                    </h1>
                    <p className='text-lg text-slate-600 font-medium max-w-3xl leading-relaxed'>
                        Enterprise Linux, DevOps deployment pipelines, AI Infrastructure, and Cloud Engineering knowledge base.
                    </p>
                </div>

                {/* SEARCH COMPONENT (White floating element) */}
                <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm">
                    <SearchBar keyword={keyword} setKeyword={setKeyword} />
                </div>

                {/* ARTICLES CONTAINER */}
                <div className='space-y-4 bg-transparent'>
                    <div className="flex items-center justify-between px-1">
                        <h2 className="text-xs font-bold uppercase tracking-widest text-slate-400">
                            Core System Repositories
                        </h2>
                        <span className="text-xs font-mono font-bold text-blue-600 bg-blue-50 px-2.5 py-1 rounded-full border border-blue-100">
                            {filteredDocs.length} Guides Available
                        </span>
                    </div>

                    {/* WHITE DOC CARDS: These will now float elegantly over the gray background */}
                    <div className='grid gap-4 bg-transparent'>
                        {filteredDocs.map((doc) => (
                            <Link
                                key={doc.id}
                                to={`/${doc.slug}`}
                                className='group bg-white rounded-2xl p-6 border border-slate-200/80 hover:border-blue-500 shadow-sm hover:shadow-md transition-all duration-150 block relative overflow-hidden'
                            >
                                <div className="absolute top-0 bottom-0 left-0 w-1.5 bg-slate-200 group-hover:bg-blue-600 transition-colors"></div>
                                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 pl-2 bg-transparent">
                                    <div className="space-y-1 bg-transparent">
                                        <h3 className='text-xl font-bold text-slate-900 group-hover:text-blue-600 transition-colors tracking-tight'>
                                            {doc.title}
                                        </h3>
                                        <span className="inline-block text-[10px] font-black text-slate-500 bg-slate-100 uppercase tracking-wider px-2 py-0.5 rounded border border-slate-200">
                                            {doc.category || "General"}
                                        </span>
                                    </div>
                                    <div className="hidden sm:flex items-center justify-center w-8 h-8 rounded-lg bg-slate-50 group-hover:bg-blue-50 border border-slate-200/60 text-slate-400 group-hover:text-blue-600 transition-colors shrink-0">
                                        <svg className="w-4 h-4 transform group-hover:translate-x-0.5 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 5l7 7-7 7" />
                                        </svg>
                                    </div>
                                </div>
                            </Link>
                        ))}
                    </div>
                </div>

            </div>
        </div>
    </div>
);
}

export default Home;
