import { useEffect, useState } from 'react';

import axios from 'axios';

import { Link } from 'react-router-dom';

function AdminList() {

    const [docs, setDocs] = useState([]);

    const loadDocuments = () => {

        axios
            .get('/api/admin/documents')
            .then(res => {

                setDocs(res.data);
            });
    };

    useEffect(() => {

        loadDocuments();

    }, []);

    const deleteDocument = async (id) => {

        if (!window.confirm('Delete this document?')) {

            return;
        }

        await axios.delete(
            `/api/admin/document/${id}`
        );

        loadDocuments();
    };

    return (

        <div className="max-w-7xl mx-auto">

            <div className="flex justify-between mb-10">

                <div>

                    <h1 className="text-5xl font-bold">

                        Manage Documents

                    </h1>

                    <p className="text-slate-600 mt-2">

                        Edit or delete documentation

                    </p>

                </div>

                <Link
                    to="/admin"
                    className="
                        bg-blue-600
                        text-white
                        px-6
                        py-3
                        rounded-xl
                    "
                >

                    Add New

                </Link>

            </div>

            <div className="bg-white rounded-3xl border">

                <table className="w-full">

                    <thead>

                        <tr className="border-b">

                            <th className="p-5 text-left">
                                Title
                            </th>

                            <th className="p-5 text-left">
                                Category
                            </th>

                            <th className="p-5 text-left">
                                Actions
                            </th>

                        </tr>

                    </thead>

                    <tbody>

                        {
                            docs.map(doc => (

                                <tr
                                    key={doc.id}
                                    className="border-b"
                                >

                                    <td className="p-5">

                                        {doc.title}

                                    </td>

                                    <td className="p-5">

                                        {doc.category}

                                    </td>

                                    <td className="p-5 flex gap-3">

                                        <Link
                                            to={`/admin/edit/${doc.id}`}
                                            className="
                                                bg-green-600
                                                text-white
                                                px-4
                                                py-2
                                                rounded-lg
                                            "
                                        >

                                            Edit

                                        </Link>

                                        <button
                                            onClick={() =>
                                                deleteDocument(doc.id)
                                            }
                                            className="
                                                bg-red-600
                                                text-white
                                                px-4
                                                py-2
                                                rounded-lg
                                            "
                                        >

                                            Delete

                                        </button>

                                    </td>

                                </tr>
                            ))
                        }

                    </tbody>

                </table>

            </div>

        </div>
    );
}

export default AdminList;
